<template>
  <div data-sales-configuration-page>
    <PageHead title="权益包配置" desc="给明确商品或规格配置可选商品和服务，先看本次草稿效果，再确认发布应用。"><el-button v-if="returnTo" @click="router.push(returnTo)">返回来源页面</el-button><el-button @click="router.push('/sales-shopping')">权益包选购</el-button><el-button v-if="store.can('product:sales-config:create')" type="primary" data-sales-new-plan @click="openConfiguration()">新建权益包配置</el-button></PageHead>
    <section class="panel">
      <details v-if="workingCopies.length" class="working-copies"><summary>我的未生效工作草稿（{{workingCopies.length}}）</summary><p v-for="entry in workingCopies" :key="entry.copy.key"><span>{{entry.copy.planDraft?.name||entry.copy.draft.name||'未命名配置'}} · {{entry.legacy?'旧格式，需明确核对':bindingLabel(entry.copy.draft)}}</span><el-button link type="primary" @click="resumeWorking(entry.copy.key)">继续此工作草稿</el-button></p></details>
      <div class="configuration-toolbar"><el-input v-model="search" clearable placeholder="搜索配置名称或应用范围" aria-label="搜索权益包配置"/><el-button :type="tab==='plans'?'primary':'default'" plain @click="tab='plans'">配置列表</el-button><el-button :type="tab==='bindings'?'primary':'default'" plain @click="tab='bindings'">应用范围明细</el-button><el-button v-if="store.can('product:compatibility:read')" link @click="tab='relations'">商品推荐关联</el-button></div>
      <el-table v-if="tab==='plans'" :data="plans" row-key="id" data-sales-plan-table>
        <el-table-column label="配置名称" min-width="200"><template #default="{row}"><button class="record-link" @click="openConfiguration(row.id)">{{row.name}}</button><small>{{row.id}}</small></template></el-table-column>
        <el-table-column label="实际状态" width="170"><template #default="{row}"><el-tag :type="row.status==='disabled'?'info':row.publishedVersion?'success':'warning'">{{statusLabel(row)}}</el-tag></template></el-table-column>
        <el-table-column label="已发布版本" width="110"><template #default="{row}">{{row.publishedVersion?`v${row.publishedVersion}`:'尚未发布'}}</template></el-table-column>
        <el-table-column label="配置项目" width="105"><template #default="{row}">{{row.items.filter((item:SalesOptionItem)=>item.enabled).length}} 项启用</template></el-table-column>
        <el-table-column label="应用范围" min-width="230"><template #default="{row}"><span v-if="!usages(row.id).length" class="muted">尚未应用 · 可继续配置</span><button v-for="binding in usages(row.id).slice(0,2)" :key="binding.id" class="scope-link" @click="openConfiguration(row.id,binding.id)">{{bindingLabel(binding)}} · v{{binding.planVersion||'—'}}</button><span v-if="usages(row.id).length>2" class="muted">共 {{usages(row.id).length}} 个明确范围</span></template></el-table-column>
        <el-table-column label="需要处理" min-width="190"><template #default="{row}"><span :class="planIssues(row).length?'problem':'muted'">{{planIssues(row)[0]||'暂无已知配置问题'}}</span></template></el-table-column>
        <el-table-column label="操作" width="220"><template #default="{row}"><el-button link type="primary" @click="openConfiguration(row.id)">{{store.can('product:sales-config:update')?'继续配置':'查看配置'}}</el-button><el-button link @click="openConfiguration(row.id,usages(row.id)[0]?.id,true)">查看效果</el-button><el-dropdown trigger="click"><el-button link :aria-label="`${row.name}更多操作`">更多</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-if="store.can('product:sales-config:create')" @click="openConfiguration('',undefined,false,row.id)">复制后调整</el-dropdown-item><el-dropdown-item v-if="store.can('product:sales-config:publish')" @click="setStatus(row)">{{row.status==='disabled'?'启用配置':'停用配置'}}</el-dropdown-item><el-dropdown-item @click="usagePlanId=row.id;tab='bindings'">查看全部应用范围</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template></el-table-column>
      </el-table>
      <template v-else-if="tab==='bindings'"><p class="muted">范围固定引用明确版本；新版本不会自动升级其他范围。</p><el-button v-if="store.can('product:sales-config:update')" data-sales-new-binding @click="openConfiguration()">配置新的应用范围</el-button><el-button v-if="usagePlanId" link @click="usagePlanId=''">查看全部范围</el-button><el-table :data="bindings" row-key="id" data-sales-binding-table><el-table-column label="应用范围" min-width="260"><template #default="{row}">{{bindingLabel(row)}}<small>{{row.id}}</small></template></el-table-column><el-table-column label="使用配置" min-width="210"><template #default="{row}">{{row.mode==='none'?'此范围不显示权益包选项':`${planName(row.planId)} · v${row.planVersion||'—'}`}}</template></el-table-column><el-table-column label="状态" width="130"><template #default="{row}">{{row.enabled?'已启用':'草稿／停用'}}</template></el-table-column><el-table-column label="操作" width="160"><template #default="{row}"><el-button link type="primary" @click="openConfiguration(row.planId||'',row.id)">继续配置此范围</el-button></template></el-table-column></el-table></template>
      <template v-else><p>推荐关联属于权益包搭配建议，不能作为已确认兼容性依据。</p><el-button v-if="store.can('product:compatibility:create')" data-sales-new-relation @click="relationId='';relationOpen=true">新增商品推荐关联</el-button><el-button link @click="router.push('/compatibility?tab=workbench')">直接适用声明到兼容性维护</el-button><el-table :data="relations" row-key="id" data-sales-relation-table><el-table-column label="来源商品"><template #default="{row}">{{skuName(row.sourceSkuId)}}</template></el-table-column><el-table-column label="推荐商品"><template #default="{row}">{{skuName(row.targetSkuId)}}</template></el-table-column><el-table-column label="状态" width="130"><template #default="{row}">{{row.enabled?'仅搭配推荐':'已停用'}}</template></el-table-column><el-table-column label="操作" width="120"><template #default="{row}"><el-button link @click="relationId=row.id;relationOpen=true">查看／编辑</el-button></template></el-table-column></el-table></template>
      <el-alert v-if="error" :title="error" type="error" :closable="false"/>
      <details v-if="unknownRows.length"><summary>不支持的配置版本，只读保留（{{unknownRows.length}}）</summary><p v-for="item in unknownRows" :key="item.id">{{item.name}} · {{item.id}}</p></details>
    </section>
    <SalesConfigurationWorkspace v-if="workspaceOpen" ref="workspace" v-model="workspaceOpen" :plan-id="query('planId')||query('plan')||undefined" :copy-id="query('copyId')||undefined" :binding-id="query('bindingId')||query('binding')||undefined" :plan-version="requestedPlanVersion" :model-id="query('modelId')||query('template')||undefined" :version-id="query('version')||query('versionId')||null" :node-id="query('nodeId')||query('node')||undefined" :readonly="query('readonly')==='1'||!canConfigure" :resume-token="query('task')||undefined" @saved="published" @update:model-value="value=>{if(!value)closeConfiguration()}"/>
    <SalesProductRelationEditor v-model="relationOpen" :relation-id="relationId"/>
  </div>
</template>
<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter,onBeforeRouteUpdate,onBeforeRouteLeave} from 'vue-router'
import {ElMessageBox} from 'element-plus'
import {compatibilityReturnLocation} from '../domain/compatibilityNavigation'
import PageHead from '../components/PageHead.vue'
import SalesConfigurationWorkspace from '../components/sales-configuration/SalesConfigurationWorkspace.vue'
import SalesProductRelationEditor from '../components/sales-configuration/SalesProductRelationEditor.vue'
import {useCatalogStore,uid} from '../stores/catalog'
import {planProblems,salesSignature} from '../domain/salesConfiguration'
import {savedSkuName} from '../domain/productList'
import type {SalesOptionBinding,SalesOptionPlan,SalesOptionItem} from '../domain/salesConfigurationTypes'
const store=useCatalogStore(),route=useRoute(),router=useRouter(),search=ref(''),tab=ref('plans'),usagePlanId=ref(''),error=ref(''),workspaceOpen=ref(false),workspace=ref<InstanceType<typeof SalesConfigurationWorkspace>>(),relationOpen=ref(false),relationId=ref('')
const query=(key:string)=>typeof route.query[key]==='string'?route.query[key] as string:''
const requestedPlanVersion=computed(()=>query('planVersion')?Number(query('planVersion')):undefined)
const returnTo=computed(()=>compatibilityReturnLocation(query('returnTo'))||'')
const canConfigure=computed(()=>store.can('product:sales-config:create')||store.can('product:sales-config:update'))
const workingCopies=computed(()=>{workspaceOpen.value;return store.can('product:sales-config:read')?store.listSalesBindingWorkingCopies().copies:[]})
const browsingKey=computed(()=>`iyge-configuration-browse:${JSON.stringify([store.activeUserId,store.previewUserId])}`)
function rememberBrowsing(){try{sessionStorage.setItem(browsingKey.value,JSON.stringify({search:search.value,tab:tab.value,scroll:document.querySelector('.content')?.scrollTop||0}))}catch{/* Browsing stays usable when private storage is unavailable. */}}
function restoreBrowsing(){try{const value=JSON.parse(sessionStorage.getItem(browsingKey.value)||'null');if(!value)return;search.value=typeof value.search==='string'?value.search:'';tab.value=['plans','bindings','relations'].includes(value.tab)?value.tab:'plans';requestAnimationFrame(()=>{const element=document.querySelector('.content');if(element)element.scrollTop=Number(value.scroll)||0})}catch{/* No fallback to another identity's state. */}}
restoreBrowsing()
const needle=computed(()=>search.value.trim().toLocaleLowerCase())
const plans=computed(()=>(store.data.salesOptionPlans||[]).filter(item=>item.schemaVersion===1&&`${item.name} ${usages(item.id).map(bindingLabel).join(' ')}`.toLocaleLowerCase().includes(needle.value)))
const bindings=computed(()=>(store.data.salesOptionBindings||[]).filter(item=>item.schemaVersion===1&&(!usagePlanId.value||item.planId===usagePlanId.value)&&`${item.name} ${bindingLabel(item)}`.toLocaleLowerCase().includes(needle.value)))
const relations=computed(()=>(store.data.salesProductRelations||[]).filter(item=>item.schemaVersion===1&&item.kind==='recommendation'&&`${skuName(item.sourceSkuId)} ${skuName(item.targetSkuId)}`.toLocaleLowerCase().includes(needle.value)))
const unknownRows=computed(()=>(store.data.salesOptionPlans||[]).filter(item=>item.schemaVersion!==1))
const planName=(id:string|null)=>store.data.salesOptionPlans?.find(item=>item.id===id)?.name||'配置引用失效'
function usages(id:string){return (store.data.salesOptionBindings||[]).filter(item=>item.schemaVersion===1&&item.planId===id)}
function planIssues(plan:SalesOptionPlan){return planProblems(store.data,plan)}
function statusLabel(plan:SalesOptionPlan){if(plan.status==='disabled')return '已停用';if(!plan.publishedVersion)return '草稿';const version=plan.versions.find(item=>item.version===plan.publishedVersion);return version&&salesSignature([version.name,version.items,version.rules])!==salesSignature([plan.name,plan.items,plan.rules])?'已发布 · 草稿有修改':'已发布'}
function bindingLabel(binding:SalesOptionBinding){if(binding.scope.kind==='products')return `${binding.scope.familyIds.length} 个 SPU／${binding.scope.skuIds.length} 个 SKU`;const scope=binding.scope,model=store.data.specCanvases.find(item=>item.templateId===scope.modelId),version=store.data.specModelVersions.find(item=>item.id===scope.versionId&&item.templateId===scope.modelId);return `${model?.name||scope.modelId} · ${version?.versionName||(scope.versionId?'版本失效':'模型草稿')}${scope.selector?' · 明确规格范围':''}`}
function skuName(id:string){const sku=store.data.skus.find(item=>item.id===id);return sku?savedSkuName(sku):`商品已失效 · ${id}`}
function openConfiguration(planId='',bindingId?:string,readonly=false,copyId?:string){void router.push({path:'/sales-configurations',query:{...route.query,configure:'1',planId:planId||undefined,bindingId,readonly:readonly?'1':undefined,planVersion:undefined,copyId,task:undefined,modelId:undefined,version:undefined,versionId:undefined,nodeId:undefined,plan:undefined,binding:undefined,template:undefined,node:undefined}})}
function resumeWorking(key:string){try{const token=uid('configuration-return');sessionStorage.setItem(`iyge-config-return:${JSON.stringify([store.activeUserId,store.previewUserId,token])}`,JSON.stringify({key}));void router.push({path:'/sales-configurations',query:{configure:'1',task:token,returnTo:route.query.returnTo}})}catch{error.value='无法保存返回上下文，工作草稿仍保留。'}}
function published(planId:string,bindingId?:string){void router.replace({path:'/sales-configurations',query:{...route.query,configure:'1',planId:planId||undefined,bindingId,task:undefined,planVersion:undefined,copyId:undefined,modelId:undefined,template:undefined,nodeId:undefined,node:undefined,version:undefined,versionId:undefined}})}
function closeConfiguration(){workspaceOpen.value=false;const next={...route.query};for(const key of ['configure','planId','plan','bindingId','binding','copyId','modelId','template','version','versionId','nodeId','node','task','readonly','planVersion'])delete next[key];void router.replace({query:next})}
watch(()=>route.fullPath,()=>{workspaceOpen.value=!!(query('configure')||query('planId')||query('plan')||query('bindingId')||query('binding')||query('modelId')||query('template')||query('task'));if(query('tab')==='bindings')tab.value='bindings';if(query('relationId')){relationId.value=query('relationId');relationOpen.value=true}},{immediate:true})
watch([()=>store.activeUserId,()=>store.previewUserId],()=>{workspaceOpen.value=false;relationOpen.value=false;usagePlanId.value='';search.value=''})
async function setStatus(plan:SalesOptionPlan){const owner=store.activeUserId,preview=store.previewUserId;try{await ElMessageBox.confirm(`${plan.status==='disabled'?'启用':'停用'}「${plan.name}」？当前选购会重新核对，已有清单保持原样。`,'权益包配置状态')}catch{return}try{const result=await store.setSalesOptionPlanStatus({id:plan.id,status:plan.status==='disabled'?'available':'disabled',expectedRevision:plan.revision,requestId:uid('configuration-status')},()=>owner===store.activeUserId&&preview===store.previewUserId);if(!result.ok)error.value=result.message||'状态未保存。'}catch(cause){error.value=cause instanceof Error?cause.message:String(cause)}}
onBeforeRouteUpdate(async(to,from)=>{if(workspaceOpen.value&&to.fullPath!==from.fullPath&&workspace.value){if(!await workspace.value.canDiscard())return false;workspace.value.acceptContextChange()}return true})
onBeforeRouteLeave(async()=>{if(workspaceOpen.value&&workspace.value){if(!await workspace.value.canDiscard())return false;workspace.value.acceptContextChange()}rememberBrowsing();return true})
</script>
<style scoped>.configuration-toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:16px}.configuration-toolbar>.el-input{width:300px;max-width:100%}.record-link,.scope-link{border:0;background:none;color:var(--el-color-primary);font:inherit;cursor:pointer;text-align:left;padding:3px 0}.scope-link{display:block;font-size:12px}.muted,small{color:var(--el-text-color-secondary);font-size:12px}small{display:block}.problem{color:var(--el-color-warning);font-size:12px}button:focus-visible{outline:2px solid var(--el-color-primary);outline-offset:2px}.panel{min-width:0}details{margin-top:14px}</style>
